create extension if not exists pgcrypto;
create table if not exists local_estoque(id uuid primary key default gen_random_uuid(),codigo text unique not null,nome text not null,tipo text not null check(tipo in('CD','PONTO_APOIO','TECNICO','TRANSITO','DEVOLUCAO','AVARIA')),usuario_responsavel text,ativo boolean default true,created_at timestamptz default now());
create table if not exists requisicoes(id uuid primary key default gen_random_uuid(),codigo text unique not null,codigo_externo text unique not null,tipo text not null,origem text not null,destino text not null,tecnico text,prioridade text default 'NORMAL',status text default 'RECEBIDA',created_at timestamptz default now());
create table if not exists requisicao_itens(id uuid primary key default gen_random_uuid(),requisicao_id uuid references requisicoes(id) on delete cascade,sku text not null,produto text not null,quantidade numeric(14,3) check(quantidade>0),qtd_atendida numeric(14,3) default 0,unidade text default 'UN',serial text);
create table if not exists estoque(id uuid primary key default gen_random_uuid(),local_codigo text not null,sku text not null,produto text not null,quantidade numeric(14,3) default 0,unidade text default 'UN',unique(local_codigo,sku));
create table if not exists contratos(id uuid primary key default gen_random_uuid(),codigo text unique not null,cliente text not null,status text default 'ATIVO',endereco_instalacao text,created_at timestamptz default now());
create table if not exists ordens_servico(id uuid primary key default gen_random_uuid(),codigo text unique not null,codigo_externo text unique,contrato_id uuid references contratos(id),cliente text not null,tecnico text not null,tipo text not null,status text default 'PENDENTE',endereco text,data_programada timestamptz,created_at timestamptz default now());
create table if not exists os_itens(id uuid primary key default gen_random_uuid(),os_id uuid references ordens_servico(id) on delete cascade,sku text not null,produto text not null,qtd_prevista numeric(14,3),qtd_reservada numeric(14,3) default 0,qtd_utilizada numeric(14,3) default 0,unidade text default 'UN',destinacao text check(destinacao in('CONSUMO','COMODATO','VENDA')),serial text);
create table if not exists reservas(id uuid primary key default gen_random_uuid(),os_id uuid references ordens_servico(id),sku text not null,local_codigo text not null,quantidade numeric(14,3) check(quantidade>0),status text default 'ATIVA',created_at timestamptz default now());
create table if not exists ativos(id uuid primary key default gen_random_uuid(),sku text not null,produto text not null,serial text unique not null,mac text unique,status text not null,local_codigo text,contrato_id uuid references contratos(id),propriedade text default 'EMPRESA',created_at timestamptz default now());
create table if not exists movimentos(id uuid primary key default gen_random_uuid(),tipo text not null,origem text,destino text,sku text not null,quantidade numeric(14,3) check(quantidade>0),requisicao_id uuid references requisicoes(id),os_id uuid references ordens_servico(id),ativo_id uuid references ativos(id),usuario text,created_at timestamptz default now());
create table if not exists eventos(id bigint generated always as identity primary key,entidade text not null,entidade_id text not null,evento text not null,detalhe jsonb default '{}'::jsonb,created_at timestamptz default now());
create index if not exists idx_req_status on requisicoes(status);create index if not exists idx_os_status on ordens_servico(status,tecnico);create index if not exists idx_est_local on estoque(local_codigo,sku);create index if not exists idx_ativo_local on ativos(status,local_codigo);
insert into local_estoque(codigo,nome,tipo,usuario_responsavel) values('CD-FOR','CD Fortaleza','CD',null),('TRANSITO','Estoque em Trânsito','TRANSITO',null),('TEC-060','Tony Moreira','TECNICO','Tony Moreira'),('AVARIA-FOR','Avaria Fortaleza','AVARIA',null) on conflict(codigo) do nothing;
